UPDATE "StaticPageContent"
SET "blocks" = $json$
[
  {"type":"hero","version":1,"data":{"title":"О компании","subtitle":"","variant":"pageIntro"}},
  {"type":"imageText","version":1,"data":{"variant":"aboutLead","title":"Prime Electronics — ваш надежный проводник в мире современных технологий","html":"<p>Мы предлагаем только премиальную электронику от ведущих мировых брендов: новейшие смартфоны, планшеты, ноутбуки, умные часы и аксессуары с официальной гарантией. Наша миссия — делать высокие технологии доступными каждому.</p><p>Команда Prime Electronics состоит из опытных специалистов, которые увлечены технологиями и готовы поделиться своими знаниями. Мы помогаем подобрать идеальное устройство под любые потребности и бюджет, обеспечивая высокий уровень сервиса на всех этапах покупки.</p><p>Покупая в Prime Electronics, вы выбираете качество, уверенность и профессиональный подход. У нас всегда актуальные модели, индивидуальное обслуживание и забота о каждом клиенте.</p>","image":"/images/prime_banner.png","mobileImage":"/images/banner_mob.png","imageAlt":"Prime Electronics","imageSide":"right"}},
  {"type":"stats","version":1,"data":{"items":[{"value":"7+","label":"лет на рынке"},{"value":"50 000+","label":"довольных клиентов"},{"value":"1 000+","label":"товаров в наличии"},{"value":"99%","label":"положительных отзывов"}]}},
  {"type":"cards","version":1,"data":{"variant":"iconFeatures","title":"Почему выбирают нас","centerTitle":true,"columns":3,"items":[{"icon":"/icons/check.svg","title":"Эксклюзивные новинки","text":"Всегда в наличии последние модели премиальной электроники раньше, чем у конкурентов. Официальные поставки и выгодные цены."},{"icon":"/icons/check.svg","title":"Гарантия подлинности","text":"100% оригинальная техника с официальной гарантией производителя и полной поддержкой авторизованных сервисных центров."},{"icon":"/icons/check.svg","title":"Выгодные условия","text":"Гибкие варианты оплаты, рассрочка без переплат и персональные предложения для каждого клиента."},{"icon":"/icons/check.svg","title":"Экспертная поддержка","text":"Профессиональные консультации по выбору техники и помощь в настройке устройств от наших специалистов."},{"icon":"/icons/check.svg","title":"Быстрая доставка","text":"Доставка по всей России, самовывоз в день заказа из наших магазинов в удобное для вас время."},{"icon":"/icons/check.svg","title":"Программа лояльности","text":"Накопительные бонусы, специальные акции и эксклюзивные предложения для постоянных клиентов."}]}},
  {"type":"cta","version":1,"data":{"variant":"gradient","title":"","text":"Посетите наши магазины или закажите онлайн — мы всегда рады помочь вам найти идеальное устройство","buttonText":"Перейти в каталог","buttonHref":"/catalog"}}
]
