UPDATE "StaticPageContent"
SET "blocks" = $json$
[
  {"type":"hero","version":1,"data":{"variant":"warranty","title":"Гарантия и сервисное обслуживание","subtitle":"Мы гарантируем качество каждого устройства и предоставляем полный спектр сервисных услуг. Ваше спокойствие — наша забота."}},
  {"type":"cards","version":1,"data":{"variant":"warrantyIcons","title":"Гарантийные случаи","subtitle":"На что распространяется гарантийное обслуживание","items":[{"icon":"wrench","title":"Производственный брак","text":"Любые дефекты, возникшие по вине производителя: неисправность экрана, батареи, камер, динамиков и других компонентов"},{"icon":"laptop","title":"Программные сбои","text":"Проблемы с операционной системой, зависания, ошибки обновления и другие программные неполадки"},{"icon":"search","title":"Заводские дефекты","text":"Скрытые дефекты, проявившиеся в процессе эксплуатации: отклеивание экрана, проблемы с корпусом"},{"icon":"battery","title":"Проблемы с зарядкой","text":"Неисправность разъема зарядки, проблемы с беспроводной зарядкой, быстрый разряд батареи"}]}},
  {"type":"richText","version":1,"data":{"variant":"warrantyTerms","title":"Условия гарантийного обслуживания","html":"<div><h4>1. Основные обязательства</h4><p>Продавец обеспечивает проведение гарантийного ремонта и технического обслуживания товара в течение всего установленного гарантийного срока.</p></div><div><h4>2. Что не покрывается гарантией</h4><p>Гарантия не действует при возникновении следующих повреждений и ситуаций:</p><ul><li><strong>Неправильное использование:</strong> подключение с нарушением инструкции, эксплуатация устройства в нештатных режимах.</li><li><strong>Внешние факторы:</strong> скачки напряжения, стихийные бедствия, иные сторонние обстоятельства.</li><li><strong>Физические воздействия:</strong> механические дефекты, тепловые повреждения (перегрев) устройства.</li><li><strong>Форсирование режимов (оверклокинг):</strong> выход из строя процессора, материнской платы и других компонентов в результате «разгона» гарантии не подлежит.</li></ul></div><div><h4>3. Допустимые нормы состояния экрана</h4><p>Наличие до 4 (четырех) «битых» или выпавших точек на ЖК-дисплее не признается существенным недостатком для iPad, iPhone, MacBook, iMac и других устройств с жидкокристаллическими экранами.</p><p>Данный пункт согласован с Законом о защите прав потребителей и Постановлением Правительства РФ № 55 от 19.01.1998 г. (ред. от 20.10.1998 г.) «Об утверждении Перечня непродовольственных товаров надлежащего качества, не подлежащих возврату или обмену».</p></div><div><h4>4. Дополнительные случаи снятия с гарантии</h4><p>Сервисное обслуживание не предоставляется, если:</p><ul><li>Обнаружены следы самостоятельного вскрытия, ремонта или любого вмешательства в конструкцию устройства.</li><li>Имеются повреждения от ударов, падений или иного механического воздействия.</li><li>Заводские серийные номера удалены, испорчены, затерты или содержат следы исправлений.</li></ul></div><div><h4>5. Порядок определения причин поломки</h4><p>Диагностика причин возникновения дефектов проводится специалистами гарантийного отдела магазина.</p><p>Если клиент не согласен с их заключением, он вправе организовать независимую экспертизу в порядке, установленном Законом о защите прав потребителей.</p></div><div><h4>6. Особые условия для периферии</h4><p>Гарантийное обслуживание мониторов, принтеров, сканеров и иного периферийного оборудования, где гарантия предоставляется производителем, осуществляется в авторизованных сервисных центрах с момента покупки. Доставка оборудования в сервисный центр и обратно производится за счет покупателя.</p></div><div><h4>7. Согласие с условиями</h4><p>Совершая покупку, вы автоматически подтверждаете, что ознакомлены и согласны с настоящими правилами гарантийного обслуживания.</p></div>"}},
  {"type":"steps","version":1,"data":{"variant":"warranty","title":"Как воспользоваться гарантией","subtitle":"Простой процесс в 4 шага","items":[{"number":"01","title":"Обнаружение проблемы","text":"При обнаружении неисправности свяжитесь с нами любым удобным способом"},{"number":"02","title":"Диагностика","text":"Привезите устройство в сервисный центр или закажите бесплатный курьер для диагностики"},{"number":"03","title":"Решение проблемы","text":"После диагностики мы отремонтируем или заменим устройство в соответствии с условиями гарантии"},{"number":"04","title":"Получение устройства","text":"Заберите отремонтированное устройство или получите его с доставкой"}]}},
  {"type":"cards","version":1,"data":{"variant":"warrantyIcons","benefits":true,"title":"Преимущества нашего сервиса","subtitle":"Почему клиенты выбирают нас","items":[{"icon":"zap","title":"Быстрый ремонт","text":"Средний срок ремонта — 5-7 дней, экспресс-ремонт — 1-3 дня"},{"icon":"check","title":"Оригинальные запчасти","text":"Используем только оригинальные комплектующие от производителя"},{"icon":"eye","title":"Прозрачность","text":"Информируем о статусе ремонта на каждом этапе"},{"icon":"shield","title":"Гарантия на ремонт","text":"3 месяца гарантии на выполненные работы"}]}},
  {"type":"cta","version":1,"data":{"variant":"warrantyDark","title":"Нужна помощь с гарантийным обслуживанием?","text":"Свяжитесь с нами, и мы поможем решить любой вопрос по гарантийному обслуживанию вашего устройства","buttonText":"Связаться с нами","buttonHref":"/contacts","button2Text":"Перейти в каталог","button2Href":"/catalog"}}
]
$json$::jsonb,
"updatedAt" = CURRENT_TIMESTAMP
WHERE "path" = '/warranty';

